mapper.select:
SELECT
A.PRODID prodId,
A.ORG_CODE orgCode,
IFNULL(b.prod_name,a.reg_code) orgName,
b.PROD_NAME prodName,
A.REG_CODE regCode,
b.OPERATE_MODE operateMode,
DATE_FORMAT(b.VDATE,'%Y-%m-%d') vdate,
DATE_FORMAT(b.MDATE,'%Y-%m-%d') mdate,
DATE_FORMAT(A.CREATE_TIME,'%Y-%m-%d') generateDate,
A.REMARK remark,
c.PATH
FROM CHB_PRDRESIST_CODE A
left join chb_prd_baseinfo b
on b.prod_id = a.PRODID
left join sys_upload_file_info c
on c.SEQ_NO=a.REG_CODE



			#{prodid,jdbcType=VARCHAR}




			#{investor,jdbcType=VARCHAR}



		AND DATE_FORMAT(b.VDATE,'%Y-%m-%d') >= #{vdateStart}


		AND DATE_FORMAT(b.VDATE,'%Y-%m-%d') <= #{vdateEnd}


		AND DATE_FORMAT(b.MDATE,'%Y-%m-%d') >= #{mdateStart}


		AND DATE_FORMAT(b.MDATE,'%Y-%m-%d') <= #{mdateEnd}



			#{regCode,jdbcType=VARCHAR}



		AND A.REG_CODE is null




			#{orgCode,jdbcType=VARCHAR}






			#{key,jdbcType=VARCHAR}



ORDER BY A .UPDATE_TIME DESC,A .PRODID ASC

SELECT DISTINCT B.PRODID id, B.PRODNAME text FROM CHB_PRDRESIST_CODE B
B.PRODID like #{likeStr} or B.PRODNAME like #{likeStr}
order by B.PRODID

select A.Prodid prodId
from CHB_PRDRESIST_CODE A


		#{bankCode.prodId,jdbcType=VARCHAR}

	and A.org_code = #{orgCode,jdbcType=VARCHAR}

select sum(num) from
(select COUNT(ACCOUNT) num from CHB_EQUDET where
STATUS = #{status}

	#{prodId,jdbcType=VARCHAR}

union all
select COUNT(PRODID) num from CHB_EQUPERIOD where
STATUS = #{status}

	#{prodId,jdbcType=VARCHAR}

union all
select COUNT(PRD_REGIST_CODE) num from CHB_INVESTHOLD_INFO where
STATUS = #{status}

	#{prdRegistCode,jdbcType=VARCHAR}
)

mapper.update:
begin
update CHB_PRDRESIST_CODE set OPERATE_MODE = #{item.operateMode}, UPDATE_TIME = sysdate where PRODID = #{item.prodId}
;end;

mapper.select:
select
cpc.REG_CODE regCode
from
CHB_PRDRESIST_CODE cpc


		cpc.REG_CODE = #{regCode,jdbcType=VARCHAR}


		and cpc.PRODID != #{prodId,jdbcType=VARCHAR}
